<script setup lang="ts">
import {computed,ref,watch} from 'vue';import {Search,ArrowLeft} from 'lucide-vue-next';import Chart from '../components/Chart.vue';import {useAppStore,fmt,pct,time,labels,timestampLabels} from '../store';import type {TrainingRun,ScenarioAnalysis} from '../types';
const app=useAppStore();const search=ref(''),sort=ref('last'),verdict=ref(''),range=ref<[Date,Date]|null>(null),rows=ref<TrainingRun[]>([]),pb=ref<number[]>([]),detail=ref<ScenarioAnalysis|null>(null),loading=ref(false);
const scenarios=computed(()=>{const v=(app.data?.scenarios??[]).filter(s=>s.name.toLowerCase().includes(search.value.toLowerCase()) && (!verdict.value||s.verdict===verdict.value));return v.slice().sort((a,b)=>sort.value==='count'?b.count-a.count:sort.value==='name'?a.name.localeCompare(b.name):(b.last_trained??0)-(a.last_trained??0));});
let requestId=0;async function load(){if(!app.selected)return;const id=++requestId;loading.value=true;try{const args={name:app.selected,from:range.value?Math.floor(range.value[0].getTime()/1000):null,to:range.value?Math.floor(range.value[1].getTime()/1000)+86399:null};const [h,a]=await Promise.all([app.call<{runs:TrainingRun[];pb_curve:number[]}>('history',args),app.call<ScenarioAnalysis>('scenario_analysis',args)]);if(id!==requestId)return;rows.value=h.runs;pb.value=h.pb_curve;detail.value=a;}catch(e){app.error=String(e);}finally{if(id===requestId)loading.value=false;}}
watch(()=>app.selected,()=>{range.value=null;load();},{immediate:true});watch(range,load);watch(()=>app.data?.sync.finished_at,load);
const option=computed(()=>({tooltip:{trigger:'axis'},legend:{data:['日常成绩','累计 PB','Accuracy'],bottom:0},grid:{left:65,right:70,top:20,bottom:65},xAxis:{type:'time'},yAxis:[{type:'value',scale:true,name:'Score'},{type:'value',min:0,max:100,name:'Accuracy %'}],series:[{name:'日常成绩',type:'line',data:rows.value.map(r=>[r.timestamp*1000,r.score]),symbolSize:5,lineStyle:{width:2,color:'#91edae'},itemStyle:{color:'#91edae'}},{name:'累计 PB',type:'line',data:rows.value.map((r,i)=>[r.timestamp*1000,pb.value[i]]),step:'end',symbol:'none',itemStyle:{color:'#eac988'},lineStyle:{type:'dashed',color:'#eac988'}},{name:'Accuracy',type:'line',yAxisIndex:1,data:rows.value.map(r=>[r.timestamp*1000,r.accuracy==null?null:r.accuracy*100]),connectNulls:false,lineStyle:{color:'#83aaf5'},itemStyle:{color:'#83aaf5'}}]}));
</script>
<template><template v-if="!app.selected"><div class="toolbar"><el-input v-model="search" placeholder="搜索场景名称" clearable style="width:330px"><template #prefix><Search :size="16"/></template></el-input><el-select v-model="sort" style="width:160px"><el-option label="最近训练优先" value="last"/><el-option label="训练次数优先" value="count"/><el-option label="按名称排序" value="name"/></el-select><el-select v-model="verdict" clearable placeholder="全部表现" style="width:170px"><el-option v-for="(label,key) in labels" :key="key" :label="label" :value="key"/></el-select><span class="muted push-right">{{scenarios.length}} 个场景</span></div><section class="panel"><el-table v-if="scenarios.length" :data="scenarios" @row-click="(s:ScenarioAnalysis)=>app.showScenario(s.name)" class="clickable"><el-table-column prop="name" label="场景" min-width="280"/><el-table-column label="PB" width="115"><template #default="{row}">{{fmt(row.pb)}}</template></el-table-column><el-table-column label="最近10次中位数" width="155"><template #default="{row}">{{fmt(row.median10)}}</template></el-table-column><el-table-column prop="count" label="训练次数" width="95"/><el-table-column label="表现信号" width="135"><template #default="{row}"><span :class="['status',row.verdict]">{{labels[row.verdict]}}</span></template></el-table-column><el-table-column label="最后训练" min-width="185"><template #default="{row}">{{time(row.last_trained)}}</template></el-table-column></el-table><div v-else class="empty">没有匹配的场景。<small>请到设置扫描 Stats 文件夹，或调整筛选条件。</small><el-button @click="app.page='settings'">打开设置</el-button></div></section></template><template v-else><div class="toolbar"><button class="text-button" @click="app.selected=''" aria-label="返回场景列表"><ArrowLeft :size="16"/> 场景列表</button><h2>{{app.selected}}</h2><el-date-picker v-model="range" type="daterange" start-placeholder="开始日期" end-placeholder="结束日期" class="push-right"/></div><div v-if="loading" class="muted">读取历史数据…</div><template v-if="detail"><div class="metrics"><div class="metric"><span>范围内 PB</span><strong>{{fmt(detail.pb)}}</strong><p>最高成绩</p></div><div class="metric"><span>最新成绩</span><strong>{{fmt(detail.latest)}}</strong><p>{{time(detail.last_trained)}}</p></div><div class="metric"><span>最近10次中位数</span><strong>{{fmt(detail.median10)}}</strong><p>实际样本 {{Math.min(10,detail.count)}} 次</p></div><div class="metric"><span>表现波动 CV</span><strong>{{fmt(detail.variability)}}<small>%</small></strong><p>最近最多 10 次 · 总计 {{detail.count}} 次</p></div></div><section class="panel"><div class="panel-heading"><h3>历史成绩曲线</h3><span class="muted">时间来源保留在记录中 · PB 在选定范围内累计</span></div><Chart v-if="rows.length" :option="option" :height="350"/><div v-else class="empty compact">选定时间范围没有记录。</div></section><div class="two-col"><section class="panel"><h3>是否真的进步？</h3><span :class="['status',detail.verdict]">{{labels[detail.verdict]}}</span><p class="body-text">{{detail.explanation}}</p><div class="detail-grid"><span>前后中位数变化 <b>{{pct(detail.median_change)}}</b></span><span>PB 变化 <b>{{pct(detail.pb_change)}}</b></span><span>7天中位数变化 <b>{{pct(detail.days7.percent)}}</b></span><span>30天中位数变化 <b>{{pct(detail.days30.percent)}}</b></span></div><p class="muted small">7/30天分别比较相邻同长度窗口；前后均至少 5 次才计算百分比。最近样本 {{detail.recent_count}} / 过去样本 {{detail.previous_count}}。</p></section><section class="panel"><h3>观察与边界</h3><p class="body-text">Accuracy 变化：{{detail.accuracy_change==null?'数据不足':`${detail.accuracy_change.toFixed(1)} 个百分点`}}</p><p>{{detail.plateau?'可能进入平台期：建议减少刷 PB，轮换相关技能场景。':'尚无充分的平台期证据。'}}</p><p>最近10次异常偏离：{{detail.anomalies}} 次。</p><p class="muted small">CV 表示相对波动，越低越稳定。平台期要求至少 30 次、跨度 21 天，不能由短期随机波动判定。动作层面的原因需要更精细的数据。</p></section></div><section class="panel"><h3>训练记录</h3><el-table :data="rows.slice().reverse()" max-height="420"><el-table-column label="时间" min-width="190"><template #default="{row}">{{time(row.timestamp)}}</template></el-table-column><el-table-column label="Score"><template #default="{row}">{{fmt(row.score)}}</template></el-table-column><el-table-column label="Accuracy"><template #default="{row}">{{row.accuracy==null?'—':`${fmt(row.accuracy*100)}%`}}</template></el-table-column><el-table-column label="Kills"><template #default="{row}">{{fmt(row.kills,0)}}</template></el-table-column><el-table-column label="Shots / Hits" width="140"><template #default="{row}">{{fmt(row.shots,0)}} / {{fmt(row.hits,0)}}</template></el-table-column><el-table-column label="时长(秒)"><template #default="{row}">{{fmt(row.duration)}}</template></el-table-column><el-table-column label="时间来源" min-width="190"><template #default="{row}">{{timestampLabels[row.timestamp_basis]??row.timestamp_basis}}</template></el-table-column><el-table-column prop="source_file" label="源文件" min-width="240" show-overflow-tooltip/></el-table></section></template></template></template>
